import { Response } from 'express';
import { User } from '../models/User';
import { logger } from '../utils/logger';
import { AppError } from '../utils/appError';
import { catchAsync } from '../utils/catchAsync';
import { AuthRequest } from '../middleware/auth';

export const getAllPatients = catchAsync(async (_req: AuthRequest, res: Response): Promise<void> => {
  try {
    const patients = await User.find({ userType: 'patient' })
      .select('-password')
      .sort({ name: 1 });
    res.json(patients);
  } catch (error) {
    logger.error('Error fetching patients:', error);
    throw new AppError('Error fetching patients', 500);
  }
});

export const getPatientById = catchAsync(async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const patient = await User.findOne({
      _id: req.params.id,
      userType: 'patient',
    }).select('-password');

    if (!patient) {
      res.status(404).json({ message: 'Patient not found' });
      return;
    }

    // Check if the requesting user has permission to view this patient
    if (req.user?.userType === 'patient' && req.user.userId !== req.params.id) {
      throw new AppError('Not authorized to view this patient', 403);
    }

    res.json(patient);
  } catch (error) {
    logger.error('Error fetching patient:', error);
    throw new AppError('Error fetching patient', 500);
  }
});

export const createPatient = catchAsync(async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const { name, email, password } = req.body;

    // Check if patient already exists
    const existingPatient = await User.findOne({ email });
    if (existingPatient) {
      res.status(400).json({ message: 'Patient already exists' });
      return;
    }

    // Create new patient
    const patient = new User({
      name,
      email,
      password,
      userType: 'patient',
    });

    await patient.save();

    res.status(201).json({
      id: patient._id,
      name: patient.name,
      email: patient.email,
    });
  } catch (error) {
    logger.error('Error creating patient:', error);
    throw new AppError('Error creating patient', 500);
  }
});

export const updatePatient = catchAsync(async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const { name, email } = req.body;
    const patient = await User.findOne({
      _id: req.params.id,
      userType: 'patient',
    });

    if (!patient) {
      res.status(404).json({ message: 'Patient not found' });
      return;
    }

    // Check if the requesting user has permission to update this patient
    if (req.user?.userType === 'doctor' && req.user.userId !== patient.doctorId) {
      throw new AppError('Not authorized to update this patient', 403);
    }

    Object.assign(patient, { name, email });
    await patient.save();

    res.json({
      id: patient._id,
      name: patient.name,
      email: patient.email,
    });
  } catch (error) {
    logger.error('Error updating patient:', error);
    throw new AppError('Error updating patient', 500);
  }
});

export const deletePatient = catchAsync(async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const patient = await User.findOneAndDelete({
      _id: req.params.id,
      userType: 'patient',
    });

    if (!patient) {
      res.status(404).json({ message: 'Patient not found' });
      return;
    }

    res.json({ message: 'Patient deleted successfully' });
  } catch (error) {
    logger.error('Error deleting patient:', error);
    throw new AppError('Error deleting patient', 500);
  }
}); 